import React, { useEffect } from "react";
import classNames from "classnames";

import { ChevronFace, ContextMenuButton, useContextMenu } from "../../structures/ContextMenu";
import UIStore from "../../../stores/UIStore";
import IconizedContextMenu, { IconizedContextMenuOptionList } from "./IconizedContextMenu";

interface Props extends Omit<React.ComponentProps<typeof ContextMenuButton>, "isExpanded" | "onClick" | "label"> {
    options: React.ReactNode[];
    title: string;
}

export const KebabContextMenu: React.FC<Props> = ({ options, title, disabled, className, ...props }) => {
    const [isOpen, button, open, close] = useContextMenu<HTMLElement>();

    useEffect(() => {
        if (disabled && isOpen) close();
    }, [disabled, isOpen, close]);

    const rect = button.current?.getBoundingClientRect();
    const onOpen = (ev: React.MouseEvent | React.KeyboardEvent): void => {
        button.current?.focus();
        open(ev);
    };
    const menuOptions = options.map((option) => {
        if (!React.isValidElement<{ onClick?: (ev: React.SyntheticEvent) => void }>(option)) return option;
        return React.cloneElement(option, {
            onClick: (ev: React.SyntheticEvent) => {
                try {
                    option.props.onClick?.(ev);
                } finally {
                    // Pointer clicks bubble to ContextMenu; AccessibleButton's keyboard activations do not.
                    if (ev.type !== "click") close();
                }
            },
        });
    });

    return <>
        <ContextMenuButton
            {...props}
            inputRef={button}
            label={title}
            isExpanded={isOpen}
            disabled={disabled}
            aria-disabled={disabled}
            className={classNames("mx_KebabContextMenu_button", className)}
            onClick={onOpen}
        >
            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
        </ContextMenuButton>
        { isOpen && rect && <IconizedContextMenu
            top={rect.bottom}
            right={UIStore.instance.windowWidth - rect.right}
            chevronFace={ChevronFace.None}
            onFinished={close}
        >
            <IconizedContextMenuOptionList red>{ menuOptions }</IconizedContextMenuOptionList>
        </IconizedContextMenu> }
    </>;
};
