.mx_KebabContextMenu_button {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
    cursor: pointer;

    &:hover, &:focus-visible {
        background-color: $menu-selected-color;
    }

    &.mx_AccessibleButton_disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }
}

.mx_KebabContextMenu_icon {
    width: 20px;
    height: 20px;
    background-color: $primary-content;
    mask: url('$(res)/img/element-icons/room/ellipsis.svg') center / contain no-repeat;
    transform: rotate(90deg);
}

