interface Props {
    device?: ExtendedDevice;
    isLoading: boolean;
    isSigningOut: boolean;
    localNotificationSettings?: LocalNotificationSettings | undefined;
    setPushNotifications?: (deviceId: string, enabled: boolean) => Promise<void> | undefined;
    onVerifyCurrentDevice: () => void;
    onSignOutCurrentDevice: () => void;
    onSignOutOtherDevices?: () => void;
    saveDeviceName: (deviceName: string) => Promise<void>;
}

const CurrentDeviceSection: React.FC<Props> = ({
    device,
    isLoading,
    isSigningOut,
    localNotificationSettings,
    setPushNotifications,
    onVerifyCurrentDevice,
    onSignOutCurrentDevice,
    onSignOutOtherDevices,
    saveDeviceName,
}) => {
    const [isExpanded, setIsExpanded] = useState(false);

    return <SettingsSubsection
        heading={<SettingsSubsectionHeading heading={_t('Current session')}>
            <KebabContextMenu
                data-testid="current-session-menu"
                title={_t('Session actions')}
                disabled={isLoading || !device || isSigningOut}
                options={[
                    <IconizedContextMenuOption key="sign-out" label={_t('Sign out')} onClick={onSignOutCurrentDevice} />,
                    onSignOutOtherDevices && <IconizedContextMenuOption
                        key="sign-out-other"
                        label={_t('Sign out all other sessions')}
                        onClick={onSignOutOtherDevices}
                    />,
                ].filter(Boolean)}
            />
        </SettingsSubsectionHeading>}
        data-testid='current-session-section'
    >
        { /* only show big spinner on first load */ }
        { isLoading && !device && <Spinner /> }
        { !!device && <>
            <DeviceTile
                device={device}
            >
                <DeviceExpandDetailsButton
                    data-testid='current-session-toggle-details'
                    isExpanded={isExpanded}
                    onClick={() => setIsExpanded(!isExpanded)}
                />
            </DeviceTile>
            { isExpanded &&
                <DeviceDetails
                    device={device}
                    localNotificationSettings={localNotificationSettings}
                    setPushNotifications={setPushNotifications}
                    isSigningOut={isSigningOut}
                    onVerifyDevice={onVerifyCurrentDevice}
                    onSignOutDevice={onSignOutCurrentDevice}
                    saveDeviceName={saveDeviceName}
                />
            }
            <br />
            <DeviceVerificationStatusCard device={device} onVerifyDevice={onVerifyCurrentDevice} />
        </>
        }
    </SettingsSubsection>;
};

export default CurrentDeviceSection;
